// Normalizaciones mínimas. es_prioritario NO se calcula acá: lo calcula la base (columna generada).
const b = $json.body ?? {};
const t = (v) => String(v ?? '').trim();
if (!$input.item.binary?.cv) throw new Error('Falta el archivo cv');
// UUID v4 sin require('crypto') (bloqueado en n8n Cloud). Solo nombra el archivo: el bucket es privado.
const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = Math.floor(Math.random() * 16);
  return (c === 'x' ? r : (r & 3) | 8).toString(16);
});
const usaRevit = t(b.usa_revit).toLowerCase();
return {
  json: {
    codigo: t(b.codigo_referente).toLowerCase(),
    nombre: t(b.nombre),
    apellido: t(b.apellido),
    email: t(b.email).toLowerCase(),
    linkedin_url: t(b.linkedin_url),
    especialidad: t(b.especialidad),
    usa_revit: usaRevit === 'si' || usaRevit === 'true',
    seniority: t(b.seniority),
    nivel_ingles: t(b.nivel_ingles),
    acepto_visibilidad: t(b.acepto_visibilidad) === 'true',
    cv_ruta: uuid + '.pdf',
  },
  binary: $input.item.binary,
};

// Traduce el resultado de la función a lo que entiende la app y decide qué hacer con el CV.
const r = $json;
const prep = $('Preparar').first().json;
const registradoNuevo = r.resultado === 'registrado' && r.repetido !== true;
return {
  json: {
    ...r,
    // La función devuelve "autorreferido"; la app solo conoce registrado | ya_registrado | codigo_invalido.
    resultado_app: r.resultado === 'autorreferido' ? 'ya_registrado' : r.resultado,
    borrar_cv: !registradoNuevo,
    cv_ruta: prep.cv_ruta,
  },
};

// Arma los mails (0 a 2). Todo lo que se muestra sale del JSON de la función; no se recalcula nada.
const SITIO = 'https://worldteams-referidos.vercel.app';
const C = { verde: '#142d2b', lima: '#d0ef76', crema: '#fff7f3', suave: '#4a5f5b' };
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const usd = (n) => 'USD ' + Number(n).toFixed(2).replace(/\.00$/, '');
const plantilla = (titulo, parrafos, boton) =>
  '<!doctype html><html lang="es"><body style="margin:0;background:' + C.crema + ';font-family:Arial,Helvetica,sans-serif;color:' + C.verde + '">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + C.crema + '"><tr><td align="center" style="padding:24px 12px">' +
  '<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#ffffff;border-radius:8px;overflow:hidden">' +
  '<tr><td style="background:' + C.verde + ';padding:20px 28px;color:' + C.lima + ';font-size:18px;font-weight:bold">WorldTeams · Programa de referidos</td></tr>' +
  '<tr><td style="padding:28px"><h1 style="margin:0 0 16px;font-size:22px;color:' + C.verde + '">' + titulo + '</h1>' +
  parrafos.map((p) => '<p style="margin:0 0 14px;font-size:16px;line-height:1.5">' + p + '</p>').join('') +
  (boton ? '<p style="margin:20px 0 0"><a href="' + boton.url + '" style="display:inline-block;background:' + C.lima + ';color:' + C.verde + ';text-decoration:none;font-weight:bold;padding:12px 22px;border-radius:8px">' + boton.texto + '</a></p>' : '') +
  '</td></tr><tr><td style="padding:16px 28px;background:' + C.crema + ';font-size:12px;color:' + C.suave + '">Mensaje automático del programa de referidos de WorldTeams.</td></tr>' +
  '</table></td></tr></table></body></html>';

const r = $('Normalizar resultado').first().json;
// El plazo sale de configuracion (nada hardcodeado); si la lectura falló, se usa un texto sin número.
const dias = Number($input.first()?.json?.valor);
const plazo = Number.isFinite(dias) && dias > 0 ? 'en hasta ' + dias + ' días hábiles' : 'en los próximos días hábiles';
const mails = [];

if (r.resultado === 'registrado' && r.repetido !== true) {
  // (2) Confirmación al candidato, nombrando a quien lo recomendó (decisión 23).
  mails.push({ json: {
    to: r.candidato.email,
    subject: 'Recibimos tu perfil, ' + r.candidato.nombre,
    html: plantilla('Recibimos tu perfil', [
      'Hola ' + esc(r.candidato.nombre) + ', <strong>' + esc(r.referente.nombre) + '</strong> te recomendó para el talent pool de WorldTeams.',
      'Revisamos tu perfil y te contactamos ' + plazo + '.',
    ]),
  } });
  // (3) Referido validado -> referente, con el bono de hito en el mismo mail si corresponde (decisión 24).
  // Si quedó en revisión no se avisa: se ve en el portal.
  if (r.estado === 'validado') {
    const p = [
      'Tu referido <strong>' + esc(r.candidato.nombre + ' ' + r.candidato.apellido) + '</strong> fue validado y ya forma parte del talent pool.',
      'Sumás <strong>' + usd(r.monto_usd) + '</strong>' + (r.ciclo_pago ? ' (ciclo de pago ' + esc(r.ciclo_pago) + ')' : '') + '.',
    ];
    if (Number(r.bono_hito_usd) > 0) p.push('Además alcanzaste un hito: <strong>bono de ' + usd(r.bono_hito_usd) + '</strong>.');
    p.push(r.proximo_hito
      ? 'Llevás ' + r.validados_anio + ' validados este año. Te faltan <strong>' + r.proximo_hito.faltan + '</strong> para el próximo bono de ' + usd(r.proximo_hito.bono_usd) + '.'
      : 'Llevás ' + r.validados_anio + ' validados este año y completaste todos los hitos.');
    mails.push({ json: {
      to: r.referente.email,
      subject: 'Tu referido ' + r.candidato.nombre + ' fue validado',
      html: plantilla('¡Tu referido fue validado!', p, { url: SITIO + '/ingresar', texto: 'Ver mi portal' }),
    } });
  }
} else if (r.resultado === 'ya_registrado') {
  // (4) No cuenta -> referente, para que no sienta que su recomendación se perdió (decisión 6).
  mails.push({ json: {
    to: r.referente.email,
    subject: 'Tu recomendación no cuenta como referido',
    html: plantilla('Esta recomendación no suma', [
      'La persona que recomendaste ya estaba en nuestra base, así que no cuenta como referido.',
      'Gracias igual por pensar en WorldTeams: seguí compartiendo tu link con otros profesionales.',
    ], { url: SITIO + '/ingresar', texto: 'Ver mi portal' }),
  } });
}
return mails;
